---
import Layout from '../layouts/Layout.astro';
import {
  readContact,
  successMessage,
  validateContact,
  type ContactErrors,
  type ContactValues,
} from '../lib/contact';

let values: ContactValues = { name: '', email: '', message: '' };
let errors: ContactErrors = {};
let success: string | undefined;

function isSameOrigin(request: Request, url: URL): boolean {
  if (request.headers.get('sec-fetch-site') === 'cross-site') return false;
  const origin = request.headers.get('origin');
  if (!origin || origin === 'null') return true;
  const allowed = new Set([url.origin]);
  if (process.env.ORIGIN) allowed.add(new URL(process.env.ORIGIN).origin);
  return allowed.has(origin);
}

if (Astro.request.method === 'POST') {
  if (!isSameOrigin(Astro.request, Astro.url)) {
    return new Response('Cross-site POST form submissions are forbidden', { status: 403 });
  }
  let data: FormData;
  try {
    data = await Astro.request.formData();
  } catch {
    data = new FormData();
  }
  values = readContact(data);
  errors = validateContact(values);
  if (Object.keys(errors).length === 0) {
    success = successMessage(values.name);
    values = { name: '', email: '', message: '' };
  } else {
    Astro.response.status = 400;
  }
}
---

<Layout title="Contact | Bookshelf" section="contact">
  <h1>Contact</h1>
  <div id="contact">
    <p class="success" role="status" hidden={!success}>{success}</p>
    <form method="post" action="/contact" novalidate>
      <div class="field">
        <label for="name">Name</label>
        <input
          id="name"
          name="name"
          type="text"
          autocomplete="name"
          value={values.name}
          aria-invalid={errors.name ? 'true' : undefined}
          aria-describedby="name-error"
        />
        <p class="error" id="name-error" hidden={!errors.name}>{errors.name}</p>
      </div>
      <div class="field">
        <label for="email">Email</label>
        <input
          id="email"
          name="email"
          type="email"
          autocomplete="email"
          value={values.email}
          aria-invalid={errors.email ? 'true' : undefined}
          aria-describedby="email-error"
        />
        <p class="error" id="email-error" hidden={!errors.email}>{errors.email}</p>
      </div>
      <div class="field">
        <label for="message">Message</label>
        <textarea
          id="message"
          name="message"
          rows="6"
          aria-invalid={errors.message ? 'true' : undefined}
          aria-describedby="message-error">{values.message}</textarea>
        <p class="error" id="message-error" hidden={!errors.message}>{errors.message}</p>
      </div>
      <button type="submit">Send</button>
    </form>
  </div>
</Layout>

<script>
  import { readContact, validateContact, type ContactField } from '../lib/contact';

  const fields: ContactField[] = ['name', 'email', 'message'];
  const container = document.querySelector<HTMLDivElement>('#contact');

  function showErrors(form: HTMLFormElement, errors: Partial<Record<ContactField, string>>) {
    for (const field of fields) {
      const control = form.elements.namedItem(field);
      const error = document.getElementById(`${field}-error`);
      const message = errors[field];
      if (error) {
        error.textContent = message ?? '';
        error.hidden = !message;
      }
      if (control instanceof HTMLElement) {
        if (message) control.setAttribute('aria-invalid', 'true');
        else control.removeAttribute('aria-invalid');
      }
    }
  }

  function bind() {
    const form = container?.querySelector('form');
    if (!form) return;
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const success = container?.querySelector<HTMLElement>('.success');
      if (success) success.hidden = true;
      const data = new FormData(form);
      const errors = validateContact(readContact(data));
      showErrors(form, errors);
      const firstInvalid = fields.find((field) => errors[field]);
      if (firstInvalid) {
        document.getElementById(firstInvalid)?.focus();
        return;
      }
      const button = form.querySelector('button');
      if (button) button.disabled = true;
      try {
        const response = await fetch(form.action, { method: 'POST', body: new URLSearchParams(data as unknown as Record<string, string>) });
        const html = await response.text();
        const next = new DOMParser().parseFromString(html, 'text/html').querySelector('#contact');
        if (!container || !next) throw new Error('Unexpected response');
        container.innerHTML = next.innerHTML;
        bind();
      } catch {
        form.submit();
      } finally {
        if (button) button.disabled = false;
      }
    });
  }

  bind();
</script>

<style>
  form {
    display: grid;
    gap: 1rem;
    max-width: 32rem;
  }
  .field {
    display: grid;
    gap: 0.25rem;
  }
  label {
    font-weight: bold;
  }
  input,
  textarea {
    font: inherit;
    padding: 0.4rem 0.5rem;
    border: 1px solid var(--line);
    border-radius: 0.3rem;
  }
  [aria-invalid='true'] {
    border-color: #b00020;
