  }
  .success {
    padding: 0.75rem 1rem;
    border: 1px solid #2e7d32;
    background: #edf7ee;
    color: #1b5e20;
    border-radius: 0.3rem;
  }
  button[type='submit'] {
    justify-self: start;
  }
</style>
EOF
